style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("https://cdn.pfps.gg/banners/4875-carti.gif") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* Optional: Make background visible behind content */
  #container, .container-main, .content, body > div {
    background-color: rgba(0, 0, 0, 0.5) !important; /* semi-transparent */
  }
}
